const reviewedSelectionCopy = [
  getGermanBarbedSelectionText,
  getGermanHardTubeSelectionText,
  getGermanThreadToBarbedSelectionText,
];

export function getGermanRemainingFittingSelectionText(value: string): string {
  const { key, tokens } = canonicalFittingDetailText(value);
  const german = germanMessages.get(key);
  if (german) {
    const leading = value.match(/^\s*/)?.[0] ?? "";
    const trailing = value.match(/\s*$/)?.[0] ?? "";
    return leading + german.replace(/\{(\d+)\}/g, (_match, index: string) => tokens[Number(index)]) + trailing;
  }
  const english = fittingDetailText(value, "en");
  for (const translate of reviewedSelectionCopy) {
    const reviewed = translate(value);
    if (reviewed !== english) return reviewed;
  }
  return english;
}
